import pandas as pd
import numpy as np
from pydantic import Field
import os


class Tools:
    def __init__(self):
        pass

    def budget_query(
        self,
        aggregate: str = Field(
            ...,
            description="Nom (partiel ou complet) d’un agrégat budgétaire, ex : 'solde', 'recettes'.",
        ),
        since_year: int = Field(None, description="Année de début (inclus)."),
        until_year: int = Field(None, description="Année de fin (inclus)."),
    ) -> dict:
        """
        Récupère les données temporelles et les statistiques d'un agrégat budgétaire depuis le CSV local.
        """

        # -------------------------------
        # CONFIGURATION DIRECTE
        # -------------------------------
        # Remplacez ce chemin si le fichier bouge
        path = r"C:\Users\gabri\Downloads\situations-budgetaires-transpose.csv"
        csv_separator = ";"

        # Vérification basique d'existence (utile pour le debug)
        if not os.path.exists(path):
            return {
                "error": f"Fichier introuvable. Le système cherche ici : {path}. Si Open WebUI tourne sous Docker, il ne peut pas voir 'C:\\Users...'."
            }

        # -------------------------------
        # 1. Chargement & Nettoyage
        # -------------------------------
        try:
            df = pd.read_csv(path, sep=csv_separator)
        except Exception as e:
            return {"error": f"Erreur lecture CSV : {str(e)}"}

        # Nettoyage des noms de colonnes
        df.columns = [str(c).strip().lower() for c in df.columns]

        if "date" not in df.columns:
            return {
                "error": "Colonne 'date' manquante dans le CSV.",
                "columns_found": list(df.columns),
            }

        # -------------------------------
        # 2. Conversion Dates
        # -------------------------------
        try:
            df["date"] = pd.to_datetime(df["date"], dayfirst=True)
        except:
            return {"error": "Format de date invalide. Attendu : JJ/MM/AAAA."}

        # -------------------------------
        # 3. Recherche Intelligente Colonne
        # -------------------------------
        search_term = aggregate.lower().strip()

        # Correspondance exacte ?
        if search_term in df.columns:
            col = search_term
        else:
            # Correspondance partielle
            matches = [c for c in df.columns if search_term in c]

            if len(matches) == 0:
                return {
                    "error": f"Aucun agrégat trouvé pour '{aggregate}'.",
                    "available_columns": [c for c in df.columns if "date" not in c][
                        :20
                    ],
                }
            elif len(matches) > 1:
                return {
                    "error": f"Ambiguïté : '{aggregate}' correspond à plusieurs colonnes : {matches}. Soyez plus précis."
                }
            else:
                col = matches[0]

        # -------------------------------
        # 4. Extraction & Filtres
        # -------------------------------
        series = df[["date", col]].copy()
        series = series.dropna(subset=[col])  # On retire les lignes vides

        if since_year:
            series = series[series["date"].dt.year >= since_year]
        if until_year:
            series = series[series["date"].dt.year <= until_year]

        if len(series) == 0:
            return {"error": "Aucune donnée trouvée pour cette période."}

        # Conversion forcée en float
        try:
            values = series[col].astype(float).values
        except:
            return {
                "error": f"La colonne '{col}' contient du texte et non des chiffres."
            }

        dates = [d.strftime("%Y-%m-%d") for d in series["date"]]

        # -------------------------------
        # 5. Statistiques & Retour
        # -------------------------------
        min_idx = int(np.argmin(values))
        max_idx = int(np.argmax(values))
        mean_val = float(np.mean(values))

        stats = {
            "aggregate_name": col,
            "count": len(values),
            "min_val": round(float(values[min_idx]), 2),
            "max_val": round(float(values[max_idx]), 2),
            "average": round(mean_val, 2),
            "sum": round(float(np.sum(values)), 2),
        }

        return {
            "status": "success",
            "stats": stats,
            "dates": dates,
            "values": [round(float(v), 2) for v in values],
        }
